package com.whaa.shop.cart.controller;import com.whaa.shop.cart.application.CartService;import com.whaa.shop.common.api.ApiResponse;import com.whaa.shop.common.security.CurrentUser;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/shop/cart") public class CartController {private final CartService service;public CartController(CartService s){service=s;}@GetMapping ApiResponse<List<CartService.CartView>> list(){return ApiResponse.ok(service.list(CurrentUser.id()));}@PostMapping ApiResponse<Void> add(@RequestBody Add r){service.add(CurrentUser.id(),r.skuId(),r.quantity());return ApiResponse.ok();}@PutMapping("/{id}")ApiResponse<Void> update(@PathVariable Long id,@RequestBody Update r){service.update(CurrentUser.id(),id,r.quantity(),r.checked());return ApiResponse.ok();}@DeleteMapping("/{id}")ApiResponse<Void> delete(@PathVariable Long id){service.delete(CurrentUser.id(),id);return ApiResponse.ok();}public record Add(Long skuId,int quantity){}public record Update(int quantity,boolean checked){}
}
